code.cpp:
class Solution {
public:
    string kthDistinct(vector<string>& arr, int k) {
        unordered_map<string, int> count;
        for (const string& s : arr) {
            count[s]++;
        }
        int distinct = 0;
        for (const string& s : arr) {
            if (count[s] == 1) {
                distinct++;
                if (distinct == k) {
                    return s;
                }
            }
        }
        return "";
    }
};
